        if corners:
            target = max(corners, key=lambda c: md(c, (ox, oy)))
            return step_towards(target)
        return step_away((ox, oy))

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("targets") or []
        if targets:
            best = min(targets, key=lambda item: md(pos(item), (sx, sy)))
            return step_towards(best)
