            cx, cy = (w - 1) / 2.0, (h - 1) / 2.0
            tx = 0 if sx == cx else (1 if sx < cx else -1)
            ty = 0 if sy == cy else (1 if sy < cy else -1)
            return [tx, ty]
        return [0, 0]

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("items") or []
    if resources:
        best = min(resources, key=lambda item: md(pos(item), (sx, sy)))
        move = step_towards(best)
        if md(pos(best), (sx, sy)) == 1:
            return move
        if ox == sx and oy == sy:
            return move
        return move

    if w > 0 and h > 0:
        cx, cy = (w - 1) / 2.0, (h - 1) / 2.0
        return [0 if sx == cx else sgn(cx - sx), 0 if sy == cy else sgn(cy - sy)]

    return step_towards((ox, oy))

